import React, { useState, useEffect } from 'react';
import PugEditor from './PugEditor';
import JEditor from './JEditor';
import HtmlPreview from './HtmlPreview';
import axios from 'axios';

const DocGen = () => {
  const [template, setTemplate] = useState('h1 Hello, #{name}');
  const [data, setData] = useState({ name: 'John Doe' });
  const [pdfcontent, setpdfcontent] = useState(null);
  const [activeTab, setActiveTab] = useState('pugEditor'); // State for active tab

  const renderPDF = async (template, data) => {
    try {
      const response = await axios.post('http://localhost:4000/generate-pdf', { template, data }, { responseType: 'blob' });
      const url = URL.createObjectURL(new Blob([response.data], { type: 'application/pdf' }));
      setpdfcontent(url);
    } catch (error) {
      console.error('Error generating PDF:', error);
    }
  };

//   useEffect(() => {
//     renderPDF(template, data);
//   }, [template, data]);

  return (
    <div style={{ padding: '20px' }}>
      <h5>PDF Template Designer</h5>

      {/* Tab Navigation with Preview Button */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <ul className="nav nav-tabs" id="docGenTabs" role="tablist" style={{ marginBottom: 0 }}>
          <li className="nav-item" role="presentation">
            <a
              className={`nav-link ${activeTab === 'pugEditor' ? 'active' : ''}`}
              id="pugEditor-tab"
              data-bs-toggle="tab"
              href="#pugEditor"
              role="tab"
              onClick={() => setActiveTab('pugEditor')}
            >
              Pug Editor
            </a>
          </li>
          <li className="nav-item" role="presentation">
            <a
              className={`nav-link ${activeTab === 'dataEditor' ? 'active' : ''}`}
              id="dataEditor-tab"
              data-bs-toggle="tab"
              href="#dataEditor"
              role="tab"
              onClick={() => setActiveTab('dataEditor')}
            >
              Data Editor
            </a>
          </li>
        </ul>
        <button
          className="btn btn-primary"
          style={{ marginLeft: '20px' }}
          onClick={() => renderPDF(template, data)}
        >
          Preview
        </button>
      </div>

      {/* Tab Content */}
      <div className="row mt-3">
        <div className="col-md-6">
          <div className="tab-content">
            <div
              className={`tab-pane fade ${activeTab === 'pugEditor' ? 'show active' : ''}`}
              id="pugEditor"
              role="tabpanel"
            >
              <PugEditor template={template} setTemplate={setTemplate} language={'pug'} />
            </div>
            <div
              className={`tab-pane fade ${activeTab === 'dataEditor' ? 'show active' : ''}`}
              id="dataEditor"
              role="tabpanel"
            >
              <JEditor data={data} setData={setData} />
            </div>
          </div>
        </div>
        <div className="col-md-6">
          {/* Live Preview Section */}
          <div className="mt-4" style={{ display: 'flex', gap: '20px' }}>
            <div style={{ flex: 1 }}>
              <HtmlPreview template={template} data={data} fileUrl={pdfcontent} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DocGen;
